selector{
    position: relative;
    overflow: hidden;
}

selector::before{
    content: "";
    position: absolute;
    width: 700px;
    height: 700px;
    background: #ff7a1a;
    border-radius: 50%;
    filter: blur(250px);
    opacity: 0.12;

    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);

    z-index: 0;
}

selector > *{
    position: relative;
    z-index: 1;
}

/* Prepara o elemento para o ambiente 3D */
selector {
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    transform-style: preserve-3d;
}

/* Aplica a inclinação e um leve zoom ao passar o mouse */
selector:hover {
    transform: perspective(1000px) rotateX(4deg) rotateY(-4deg) scale(1.03);
}

/* Opcional: Adiciona um leve brilho/sombra sob o carro ao interagir */
selector:hover img {
    filter: drop-shadow(0px 20px 30px rgba(224, 155, 92, 0.15));
    transition: filter 0.6s ease;
}

