.borda-hover{
    border:1px solid #2b2b2b;
    border-radius:12px;
    transition:.35s;
    overflow:hidden;
    position:relative;
    background:#111;
}

.borda-hover::before{
    content:"";
    position:absolute;
    inset:0;
    border-radius:12px;
    border:1px solid transparent;
    transition:.35s;
    pointer-events:none;
}

.borda-hover:hover::before{
    border-color:#ff8c00;
    box-shadow:0 0 18px rgba(255,140,0,.55);
}

