/* 1. Prepara o container */
selector {
    position: relative;
}

/* 2. Cria as linhas invisíveis */
selector::before, 
selector::after {
    content: "";
    position: absolute;
    width: 0;
    height: 0;
    border: 2px solid transparent;
    box-sizing: border-box;
    pointer-events: none;
    z-index: 10; /* Garante que fique por cima do fundo escuro */
}

/* Linha superior e direita */
selector::before {
    top: 0;
    left: 0;
}

/* Linha inferior e esquerda */
selector::after {
    bottom: 0;
    right: 0;
}

/* 3. Dispara a animação quando o Elementor entra na tela */
selector.elementor-animated::before {
    width: 100%;
    height: 100%;
    border-top-color: #e09b5c; /* Cor laranja/cobre */
    border-right-color: #e09b5c;
    /* Desenha o topo (0.5s), depois a direita (0.5s) */
    transition: width 0.5s ease-out, height 0.5s ease-out 0.5s;
}

selector.elementor-animated::after {
    width: 100%;
    height: 100%;
    border-bottom-color: #e09b5c;
    border-left-color: #e09b5c;
    /* Espera 1s (topo+direita terminarem) para desenhar embaixo e esquerda */
    transition: border-color 0s ease-out 1s, width 0.5s ease-out 1s, height 0.5s ease-out 1.5s;
}

/* 4. Extra: Para você testar enquanto edita (passando o mouse) */
selector:hover::before {
    width: 100%;
    height: 100%;
    border-top-color: #e09b5c;
    border-right-color: #e09b5c;
    transition: width 0.5s ease-out, height 0.5s ease-out 0.5s;
}
selector:hover::after {
